1	#!/usr/bin/env node
2	// trace_capture.cjs — Node 4's automatic trace-source tool.
3	//
4	// What it is: a stand-alone, zero-dependency (Node stdlib only) script that
5	// (1) discovers the live AGH named pipe on this machine without hardcoding
6	// any hash, (2) connects and performs the AGH initialize + session/load
7	// handshake for a given session key, and (3) captures every session/update
8	// notification the daemon streams back as the session's full history is
9	// replayed — converting each one, on the fly, into the JSONL event schema
10	// ({seq, ts, type, data}) that program-design/hooks/trace_visualizer.py
11	// expects for its --trace argument. The output file is directly usable as
12	// that argument; no further transformation is needed.
13	//
14	// Why it exists: the governance protocol's Node 4 step needs to cross-check
15	// the report's claims against the run's actual AGH execution trace. This
16	// script makes that possible entirely automatically — the agent's own
17	// session key (written into problem_state.json's `session_key` field at
18	// Node 0/1, per SKILL.md §0) is the only input a human never has to supply.
19	// No `agh export`, no manual file handoff.
20	//
21	// Platform note (known limitation, not a bug to fix around silently): the
22	// pipe-discovery step uses `Get-ChildItem \\.\pipe\`, which is a Windows
23	// named-pipe enumeration. On non-Windows AGH installations (Unix-domain
24	// socket daemons), this discovery mechanism will not find anything usable
25	// and the script will report "no agnes-* pipes found". This is expected to
26	// be revisited if/when the project needs cross-platform Node 4 execution;
27	// for now the project's demo/test environment is Windows-only, matching
28	// where the AGH daemon socket actually lives.
29	//
30	// Usage:
31	//   node trace_capture.cjs <sessionId> [outputFile]
32	//     <sessionId>   the AGH session key to capture; typically read from
33	//                   problem_state.json's `session_key` field for the current
34	//                   task, not hand-typed.
35	//     [outputFile]  optional; defaults to program-design/runtime/
36	//                   trace_capture_converted_<short-session-id>.jsonl.
37	//   Env overrides (for testing / pinning, not for normal Node 4 use):
38	//     AGH_SESSION_ID  fallback source for <sessionId> if the positional arg
39	//                     is omitted.
40	//     PIPE_NAME       pin a specific pipe name instead of auto-discovering.
41	//
42	// Exit codes: 0 = capture succeeded; 1 = no reachable pipe / capture
43	// error; 2 = usage error (no sessionId given).
44	//
45	// Output is a JSONL file, one event per line, in the same shape
46	// trace_visualizer.py's load_trace() expects (see that file's docstring).
47	// A first "_capture_meta" line records which sessionId was captured and
48	// when, for auditability; the remaining lines are pure trace events.
49	
50	const net = require('net');
51	const fs = require('fs');
52	const { execSync } = require('child_process');
53	const path = require('path');
54	
55	const META_KEY = 'agnes';
56	const OUT_DEFAULT_BASE = path.join(__dirname, '..', 'runtime');
57	
58	function discoverPipes() {
59	  const ps = `Get-ChildItem '\\.\\pipe\\' | Where-Object Name -like 'agnes*' | Select-Object -ExpandProperty Name`;
60	  const out = execSync(`powershell -NoProfile -Command ${JSON.stringify(ps)}`, { encoding: 'utf8' });
61	  return out.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
62	}
63	
64	function handshake(pipeName) {
65	  return new Promise((resolve) => {
66	    let buf = Buffer.alloc(0);
67	    let seq = 0;
68	    let settled = false;
69	    const finish = (ok) => {
70	      if (!settled) { settled = true; resolve(ok); }
71	    };
72	    const conn = net.connect('\\\\?\\pipe\\' + pipeName, () => {
73	      const send = (obj) => { obj.jsonrpc = '2.0'; obj.id = ++seq; conn.write(JSON.stringify(obj) + '\n'); return obj.id; };
74	      const initId = send({
75	        method: 'initialize',
76	        params: {
77	          protocolVersion: 1,
78	          clientCapabilities: {
79	            fs: { readTextFile: false, writeTextFile: false },
80	            _meta: { [META_KEY]: { capabilities: { permission: true } } },
81	          },
82	          _meta: { [META_KEY]: { clientId: 'trace-capture' } },
83	        },
84	      });
85	      conn.on('data', (chunk) => {
86	        buf = Buffer.concat([buf, chunk]);
87	        let idx;
88	        while ((idx = buf.indexOf('\n')) !== -1) {
89	          const line = buf.slice(0, idx).toString('utf8').trim();
90	          buf = buf.slice(idx + 1);
91	          if (!line) continue;
92	          let msg;
93	          try { msg = JSON.parse(line); } catch { continue; }
94	          if (msg.id === initId) {
95	            finish(!msg.error);
96	            conn.end();
97	          }
98	        }
99	      });
100	      conn.on('error', () => finish(false));
101	      setTimeout(() => finish(false), 5000);
102	    });
103	    conn.on('error', () => finish(false));
104	  });
105	}
106	
107	function captureAndConvert(sessionId, pipeName, outPath) {
108	  return new Promise((resolve) => {
109	    let buf = Buffer.alloc(0);
110	    let seq = 0;
111	    let toolCallCount = 0;
112	    let toolResultCount = 0;
113	    let placeholderCount = 0;
114	    const out = fs.createWriteStream(outPath, { encoding: 'utf8' });
115	
116	    const writeConverted = (obj) => out.write(JSON.stringify(obj) + '\n');
117	    writeConverted({ _capture_meta: { sessionId, startedAt: new Date().toISOString(), source: 'session/load stream' } });
118	
119	    const convertLine = (obj) => {
120	      if (obj._capture_meta) return;
121	      const es = obj._meta && obj._meta['ai.agnes.harness'] ? obj._meta['ai.agnes.harness'].eventSequence : null;
122	      const upd = obj.update || {};
123	      const su = upd.sessionUpdate;
124	      if (su === 'tool_call') {
125	        toolCallCount++;
126	        writeConverted({
127	          seq: es, ts: null, type: 'tool/call',
128	          data: { toolUseId: upd.toolCallId, name: upd.title, args: upd.rawInput || {} },
129	        });
130	      } else if (su === 'tool_call_update') {
131	        toolResultCount++;
132	        const status = upd.status;
133	        const contentBlocks = upd.content || [];
134	        const textParts = [];
135	        for (const b of contentBlocks) {
136	          const c = b && b.content;
137	          if (c && c.type === 'text') textParts.push(c.text || '');
138	        }
139	        writeConverted({
140	          seq: es, ts: null, type: 'tool/result',
141	          data: {
142	            toolUseId: upd.toolCallId,
143	            content: [{ type: 'text', text: textParts.join('\n') }],
144	            isError: status === 'failed',
145	          },
146	        });
147	      } else {
148	        placeholderCount++;
149	        writeConverted({
150	          seq: es, ts: null, type: 'session/start',
151	          data: { key: obj.sessionId, placeholder: su },
152	        });
153	      }
154	    };
155	
156	    const conn = net.connect('\\\\?\\pipe\\' + pipeName, () => {
157	      const send = (obj) => { obj.jsonrpc = '2.0'; obj.id = ++seq; conn.write(JSON.stringify(obj) + '\n'); return obj.id; };
158	      send({
159	        method: 'initialize',
160	        params: {
161	          protocolVersion: 1,
162	          clientCapabilities: {
163	            fs: { readTextFile: false, writeTextFile: false },
164	            _meta: { [META_KEY]: { capabilities: { permission: true } } },
165	          },
166	          _meta: { [META_KEY]: { clientId: 'trace-capture' } },
167	        },
168	      });
169	      send({
170	        method: 'session/load',
171	        params: { sessionId, cwd: '', mcpServers: [] },
172	      });
173	
174	      conn.on('data', (chunk) => {
175	        buf = Buffer.concat([buf, chunk]);
176	        let idx;
177	        while ((idx = buf.indexOf('\n')) !== -1) {
178	          const line = buf.slice(0, idx).toString('utf8').trim();
179	          buf = buf.slice(idx + 1);
180	          if (!line) continue;
181	          let msg;
182	          try { msg = JSON.parse(line); } catch { continue; }
183	          if (msg.method === 'session/update') {
184	            convertLine(msg.params || {});
185	          }
186	        }
187	      });
188	
189	      conn.on('close', () => {
190	        out.end(() => {
191	          resolve({ toolCallCount, toolResultCount, placeholderCount, outPath });
192	        });
193	      });
194	      setTimeout(() => {
195	        try { conn.destroy(); } catch { /* ignore */ }
196	      }, 20000);
197	    });
198	    conn.on('error', (e) => {
199	      out.end();
200	      resolve({ error: e.message, outPath });
201	    });
202	  });
203	}
204	
205	(async () => {
206	  const sessionId = process.argv[2] || process.env.AGH_SESSION_ID;
207	  if (!sessionId) {
208	    console.error('usage: node trace_capture.cjs <sessionId> [outputFile]  (or set AGH_SESSION_ID)');
209	    process.exit(2);
210	  }
211	  const outArg = process.argv[3];
212	  const outPath = outArg || path.join(
213	    OUT_DEFAULT_BASE,
214	    `trace_capture_converted_${sessionId.replace(/[^a-z0-9]/gi, '').slice(0, 8)}.jsonl`);
215	  fs.mkdirSync(path.dirname(outPath), { recursive: true });
216	
217	  const pinned = process.env.PIPE_NAME;
218	  let pipeNames = pinned ? [pinned] : discoverPipes();
219	  if (!pipeNames.length) {
220	    console.error('no agnes-* pipes found on this machine (see the script header for the Windows-specific discovery mechanism)');
221	    process.exit(1);
222	  }
223	  console.log('candidate pipes:', pipeNames);
224	  let chosen = null;
225	  for (const p of pipeNames) {
226	    const ok = await handshake(p);
227	    console.log(`handshake ${p}: ${ok ? 'OK' : 'rejected'}`);
228	    if (ok) { chosen = p; break; }
229	  }
230	  if (!chosen) {
231	    console.error('none of the candidate pipes accepted an initialize handshake');
232	    process.exit(1);
233	  }
234	  const result = await captureAndConvert(sessionId, chosen, outPath);
235	  if (result.error) {
236	    console.error('capture failed:', result.error);
237	    process.exit(1);
238	  }
239	  console.log(`captured: tool/call=${result.toolCallCount} tool/result=${result.toolResultCount} other=${result.placeholderCount}`);
240	  console.log('wrote:', outPath);
241	})();

